parameters.jsCode:
// Prepara los recordatorios de las citas de manana.
//
// Tres cosas que el esqueleto original no contemplaba y que importan:
//
// 1. DOBLE ENVIO. Si el flujo corre dos veces -- reintento, prueba manual,
//    reinicio de n8n -- el cliente recibe el recordatorio dos veces. Se marca
//    el evento como recordado en su propia descripcion y se saltean los que ya
//    lo tienen. La marca vive en el calendario, que es el unico estado que
//    sobrevive a un reinicio.
// 2. PREFIJO DE PAIS. Meta cobra segun el pais del destinatario: un evento con
//    un telefono extranjero se saltea, igual que en el flujo conversacional.
// 3. COMERCIO NO OPERATIVO. Un comercio suspendido no manda recordatorios.

const cfg = $('Config del recordatorio').first().json;

if (String(cfg.estadoComercio ?? 'operativo') !== 'operativo') {
  return [];
}

const prefijos = String(cfg.prefijosPermitidos ?? '')
  .split(',').map(p => p.trim()).filter(Boolean);

const MARCA = '[recordado]';
const salida = [];

for (const item of $input.all()) {
  const ev = item.json;
  const desc = String(ev.description ?? '');

  if (desc.includes(MARCA)) continue;              // ya se le aviso

  const m = desc.match(/\b(\d{8,15})\b/);          // telefono en la descripcion
  if (!m) continue;                                 // cita cargada a mano, sin telefono
  const telefono = m[1];

  if (prefijos.length && !prefijos.some(p => telefono.startsWith(p))) continue;

  const inicio = ev.start?.dateTime;
  if (!inicio) continue;                            // evento de dia completo

  const hora = new Date(inicio).toLocaleTimeString('es-BO', {
    hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'America/La_Paz',
  });

  // El titulo tiene la forma "Cita <nombre> - <servicio>".
  const titulo = String(ev.summary ?? '');
  const partes = titulo.replace(/^Cita\s+/i, '').split(/\s+[-\u2014]\s+/);
  const nombre = (partes[0] ?? '').trim() || 'cliente';
  const servicio = (partes[1] ?? '').trim() || 'su cita';

  salida.push({ json: {
    eventoId: ev.id,
    calendarioDelEvento: ev.organizer?.email || cfg.calendarioId,
    telefono,
    nombre,
    servicio,
    hora,
    descripcionOriginal: desc,
    descripcionMarcada: (desc ? desc + '\n' : '') + MARCA + ' ' + new Date().toISOString(),
    texto: String(cfg.textoRecordatorio ?? '')
      .replace('{nombre}', nombre).replace('{servicio}', servicio).replace('{hora}', hora),
  }});
}
return salida;

