// Un item por cada calendario configurado.
//
// El flujo leia UN SOLO calendario, el de por defecto. Desde que cada
// profesional tiene el suyo -- belleza y odontologia -- las citas viven en
// calendarios distintos, asi que el recordatorio no las habria visto y el
// cliente no habria recibido nada. Sin error, sin aviso.
//
// FALTABAN LAS AGENDAS DE LOS FUNCIONARIOS. Se agrego el 2026-09-06, despues de
// comprobarlo en la ejecucion #1001: se revisaron tres calendarios -- el del
// negocio y los dos del mapa de servicios -- y el de Jose no estaba en ninguno,
// porque vive en `funcionarios` y no en `calendariosPorServicio`. Su cita del
// dia siguiente a las 09:00 no recibio recordatorio y nadie se entero.
//
// Es el MISMO defecto que ya se habia corregido en el flujo de agendamiento,
// en `Calendarios a revisar`, y que aca quedo sin corregir. Cuando un dato se
// lee en dos flujos, arreglarlo en uno solo es medio arreglo.
const cfg = $('Config del recordatorio').first().json;

let mapa = {};
try { mapa = JSON.parse(cfg.calendariosPorServicio || '{}'); } catch (e) { mapa = {}; }

let equipo = [];
try {
  equipo = JSON.parse(cfg.funcionarios || '[]')
    .map((f) => f && f.calendario).filter(Boolean);
} catch (e) { equipo = []; }

const calendarios = [...new Set([cfg.calendarioId, ...Object.values(mapa), ...equipo].filter(Boolean))];
return calendarios.map(calendarioARevisar => ({ json: { ...cfg, calendarioARevisar } }));

// LA CONSOLA MANDA TAMBIEN ACA, con la misma regla que en el flujo
// conversacional: si el panel contesta, sus valores pisan; si no, se usan los
// de siempre. El peor caso es el comportamiento de ayer.
//
// LO QUE MAS IMPORTA CONECTAR EN ESTE FLUJO NO ES EL TEXTO: ES EL ESTADO.
// `Preparar recordatorios` ya cortaba cuando el comercio no estaba operativo,
// pero leia un valor escrito a mano dentro del flujo, que siempre decia
// «operativo». O sea que un comercio suspendido seguia mandando plantillas, y
// cada plantilla la cobra Meta. Con el panel conectado, suspenderlo en la
// consola corta sus recordatorios de verdad.
//
// ESTE NODO SE LLAMA «Config del recordatorio» a proposito: es el nombre que
// buscan las expresiones que ya existen en el flujo. El Set con los valores de
// respaldo paso a llamarse «Config base del recordatorio».
const base = $('Config base del recordatorio').first().json;
const r = $input.first().json ?? {};

const util = (v) => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const soloLlenos = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));

const contesto = r && typeof r === 'object' && !r.error && typeof r.tenantId === 'string';
if (!contesto) {
  return [{ json: { ...base, configDeLaConsola: false } }];
}

const op = r.operacion ?? {};
const ag = r.agendamiento ?? {};

const equipo = Array.isArray(r.funcionarios) ? r.funcionarios.map((f) => ({
  nombre: f.nombre,
  servicios: Array.isArray(f.servicios) ? f.servicios : [],
  calendario: f.calendario || f.calendarioId || '',
})).filter((f) => f.nombre) : [];

const deLaConsola = soloLlenos({
  phoneNumberId: util(r.phoneNumberId),
  calendarioId: util(op.calendarioId),
  funcionarios: equipo.length ? JSON.stringify(equipo) : undefined,
  prefijosPermitidos: Array.isArray(op.prefijosPermitidos) && op.prefijosPermitidos.length
    ? op.prefijosPermitidos.join(',') : undefined,
  // El texto del recordatorio se puede escribir desde la consola. Si el negocio
  // no lo cargo, queda el de respaldo: nunca un mensaje vacio.
  textoRecordatorio: util(ag.mensajeRecordatorio),
});

// El estado SIEMPRE sale del panel. Es el unico campo que no cae al respaldo:
// si el panel dice que el comercio no esta activo, no se manda nada.
const estadoComercio = util(r.estadoComercio) === 'activo' ? 'operativo' : 'suspendido';

return [{ json: { ...base, ...deLaConsola, estadoComercio, configDeLaConsola: true } }];
